+/**
+ * Shared key-wrapping utilities for ECIES re-wrapping operations.
+ *
+ * Extracted from ShareDialog to be shared between direct sharing (Phase 14)
+ * and invite link sharing (Phase 15). Both flows need to traverse folder
+ * metadata and re-wrap descendant keys for a target public key.
+ *
+ * Security: All plaintext key material is zeroed after use via .fill(0)
+ * in finally blocks.
+ */
+
+import type { FolderChild, FolderEntry, FilePointer } from '@cipherbox/crypto';
+import {
+  wrapKey,
+  unwrapKey,
+  hexToBytes,
+  bytesToHex,
+  decryptFolderMetadata,
+} from '@cipherbox/crypto';
+import { resolveFileMetadata } from '../../services/file-metadata.service';
+import { resolveIpnsRecord } from '../../services/ipns.service';
+import { fetchFromIpfs } from '../api/ipfs';
+import type { ChildKeyDto } from '../../api/models/childKeyDto';
+
+/**
+ * Collect all descendant keys from a folder for sharing.
+ * Traverses subfolders depth-first, re-wrapping each file and subfolder key
+ * for the target public key.
+ *
+ * Works for both direct share (recipientPubKey) and invite link (ephemeralPubKey)
+ * since the target key is parameterized.
+ *
+ * @param children - Children of the current folder
+ * @param folderKey - Decrypted AES key of the current folder (for resolving file metadata)
+ * @param ownerPrivateKey - Owner's secp256k1 private key for unwrapping ECIES keys
+ * @param targetPubKeyBytes - Target uncompressed secp256k1 public key (recipient or ephemeral)
+ * @param onProgress - Callback for progress tracking
+ */
+export async function collectChildKeys(
+  children: FolderChild[],
+  folderKey: Uint8Array,
+  ownerPrivateKey: Uint8Array,
+  targetPubKeyBytes: Uint8Array,
+  onProgress: (wrapped: number) => void
+): Promise<ChildKeyDto[]> {
+  const childKeys: ChildKeyDto[] = [];
+  let wrapped = 0;
+
+  for (const child of children) {
+    if (child.type === 'file') {
+      const fp = child as FilePointer;
+      // Resolve file metadata to get fileKeyEncrypted, then re-wrap for target
+      try {
+        const { metadata: fileMeta } = await resolveFileMetadata(fp.fileMetaIpnsName, folderKey);
+        const reWrappedFileKey = await reWrapEncryptedKey(
+          fileMeta.fileKeyEncrypted,
+          ownerPrivateKey,
+          targetPubKeyBytes
+        );
+        childKeys.push({
+          keyType: 'file' as ChildKeyDto['keyType'],
+          itemId: fp.id,
+          encryptedKey: reWrappedFileKey,
+        });
+        wrapped++;
+        onProgress(wrapped);
+      } catch (err) {
+        console.error(`Failed to re-wrap file key for ${fp.name}:`, err);
+        // Continue with other children
+      }
+    } else {
+      const folder = child as FolderEntry;
+      // Re-wrap the subfolder's folderKey for the target
+      const folderKeyRewrapped = await reWrapEncryptedKey(
+        folder.folderKeyEncrypted,
+        ownerPrivateKey,
+        targetPubKeyBytes
+      );
+      childKeys.push({
+        keyType: 'folder' as ChildKeyDto['keyType'],
+        itemId: folder.id,
+        encryptedKey: folderKeyRewrapped,
+      });
+      wrapped++;
+      onProgress(wrapped);
+
+      // Recurse into subfolder: resolve its metadata and collect its children
+      try {
+        const resolved = await resolveIpnsRecord(folder.ipnsName);
+        if (resolved) {
+          const folderKeyBytes = await unwrapKey(
+            hexToBytes(folder.folderKeyEncrypted),
+            ownerPrivateKey
+          );
+          try {
+            const encryptedBytes = await fetchFromIpfs(resolved.cid);
+            const encryptedJson = new TextDecoder().decode(encryptedBytes);
+            const encrypted = JSON.parse(encryptedJson);
+            const metadata = await decryptFolderMetadata(encrypted, folderKeyBytes);
+
+            const subKeys = await collectChildKeys(
+              metadata.children,
+              folderKeyBytes,
+              ownerPrivateKey,
+              targetPubKeyBytes,
+              (subWrapped) => {
+                onProgress(wrapped + subWrapped);
+              }
+            );
+            wrapped += subKeys.length;
+            childKeys.push(...subKeys);
+          } finally {
+            folderKeyBytes.fill(0);
+          }
+        }
+      } catch (err) {
+        console.error(`Failed to traverse subfolder ${folder.name}:`, err);
+        // Continue with other children
+      }","path":"apps/web/src/lib/crypto/key-wrapping.ts","commit_id":"6b510661a1a9e3baa6bba586bcd16d66f15d1623","original_commit_id":"6b510661a1a9e3baa6bba586bcd16d66f15d1623","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Valid — wrapped the `reWrapEncryptedKey` call for folder keys in a try-catch matching the file branch pattern. A corrupt subfolder key no longer aborts the entire traversal.","created_at":"2026-02-23T22:55:09Z","updated_at":"2026-02-23T22:55:09Z","html_url":"https://github.com/FSM1/cipher-box/pull/190#discussion_r2843488602","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/190","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2843488602"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/190#discussion_r2843488602"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/190"}},"reactions":{"url":"https://api.github.REDACTED","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":71,"original_start_line":71,"start_side":"RIGHT","line":119,"original_line":119,"side":"RIGHT",