            type="button"
            role="tab"
            aria-selected={activeTab === 'invite'}
            className={`share-tab${activeTab === 'invite' ? ' share-tab--active' : ''}`}
            onClick={() => setActiveTab('invite')}
          >
            {'INVITE LINK'}
          </button>
        </div>

