            const metadata = await decryptFolderMetadata(encrypted, itemFolderKey);

            setProgress({ current: 0, total: 0 });

            childKeys = await collectChildKeys(
              metadata.children,
              itemFolderKey,
              ownerPrivateKey,
              recipientPubKeyBytes,
              (wrapped) => setProgress({ current: wrapped, total: 0 })
