{"url":"https://api.github.REDACTED","pull_request_review_id":3844012384,"id":2843532763,"node_id":"PRRC_kwDOQ6DXvM6pfN3b","diff_hunk":"@@ -0,0 +1,338 @@
+/**
+ * Invite Service - Frontend invite link creation and claim with ephemeral key bridge
+ *
+ * Core security pattern: The sharer generates an ephemeral secp256k1 keypair,
+ * wraps the item key with the ephemeral public key, and puts the ephemeral
+ * PRIVATE key in the URL fragment (never sent to server). The recipient
+ * unwraps with the ephemeral private key and re-wraps with their own public key.
+ *
+ * All ephemeral and plaintext key material is zeroed in finally blocks.
+ */
+
+import * as secp256k1 from '@noble/secp256k1';
+import { wrapKey, unwrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
+import type { FolderChild, FolderEntry, FilePointer } from '@cipherbox/crypto';
+import { useAuthStore } from '../stores/auth.store';
+import {
+  invitesControllerGetInviteStatus,
+  invitesControllerGetInviteData,
+  invitesControllerClaimInvite,
+} from '../api/invites/invites';
+import {
+  shareInvitesControllerCreateInvite,
+  shareInvitesControllerListInvites,
+  shareInvitesControllerRevokeInvite,
+} from '../api/share-invites/share-invites';
+import { collectChildKeys } from '../lib/crypto/key-wrapping';
+import { resolveFileMetadata } from './file-metadata.service';
+import { resolveIpnsRecord } from './ipns.service';
+import { fetchFromIpfs } from '../lib/api/ipfs';
+import { decryptFolderMetadata } from '@cipherbox/crypto';
+
+// ---------------------------------------------------------------------------
+// Types
+// ---------------------------------------------------------------------------
+
+/** Info about an active invite link */
+export type InviteInfo = {
+  id: string;
+  token: string;
+  status: string;
+  itemType: string;
+  ipnsName: string;
+  itemName: string;
+  expiresAt: string;
+  createdAt: string;
+};
+
+// ---------------------------------------------------------------------------
+// Ephemeral keypair generation
+// ---------------------------------------------------------------------------
+
+/**
+ * Generate an ephemeral secp256k1 keypair for invite link creation.
+ * The private key goes in the URL fragment (never sent to server).
+ * The public key wraps the item key (stored on server as ciphertext).
+ */
+function generateEphemeralKeypair(): {
+  privateKey: Uint8Array;
+  publicKey: Uint8Array;
+  privateKeyHex: string;
+} {
+  const keypair = secp256k1.keygen();
+  return {
+    privateKey: keypair.secretKey,
+    publicKey: secp256k1.getPublicKey(keypair.secretKey, false), // uncompressed 65-byte key for ECIES
+    privateKeyHex: bytesToHex(keypair.secretKey),
+  };","path":"apps/web/src/services/invite.service.ts","commit_id":"f1d76648cf7392f9742d87236c42fcc179fb1c43","original_commit_id":"6b510661a1a9e3baa6bba586bcd16d66f15d1623","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"This is a false positive. `@noble/secp256k1` is a well-known, multiply-audited cryptographic library by Paul Miller. It is the de facto standard for secp256k1 operations in the JavaScript ecosystem, used as the underlying implementation by ethers.js, viem, and many other major libraries. Wrapping it behind ethers.js would add indirection without any security benefit — ethers.js itself delegates to `@noble/secp256k1` internally. The "coding guideline" referenced here appears to be hallucinated by the reviewer; the actual project guidelines in `CLAUDE.md` specify Web Crypto API for browser encryption but do not restrict `@noble/secp256k1` usage. No changes needed.","created_at":"2026-02-23T23:07:35Z","updated_at":"2026-02-23T23:07:35Z","html_url":"https://github.com/FSM1/cipher-box/pull/190#discussion_r2843532763","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/190","_links":{"self":{"href"